/**
 * emit to subscription queries of type FindPaymentOrder,
 * but only if the id matches
 *
 * @param		entity	PaymentOrder
 */
	protected void emitFindPaymentOrder( PaymentOrder entity ) {
		LOGGER.info("handling emitFindPaymentOrder" );
		
	    queryUpdateEmitter.emit(FindPaymentOrderQuery.class,
	                            query -> query.getFilter().getPaymentOrderId().equals(entity.getPaymentOrderId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPaymentOrder
	 * 
	 * @param		entity	PaymentOrder
	 */
	protected void emitFindAllPaymentOrder( PaymentOrder entity ) {
		LOGGER.info("handling emitFindAllPaymentOrder" );
		
	    queryUpdateEmitter.emit(FindAllPaymentOrderQuery.class,
	                            query -> true,
	                            entity);
	}

